<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {api} from '../lib/api.js'
import {currentMonth,shiftMonth,money} from '../lib/format.js'
import {barOption,pieOption,balanceOption} from '../lib/charts.js'
import Chart from '../components/Chart.vue'
import StateBox from '../components/StateBox.vue'
const month=ref(currentMonth()),span=ref(6),loading=ref(false),error=ref(''),trends=ref([]),stats=ref([]),summary=ref({income:0,expense:0,balance:0});let serial=0
const bar=computed(()=>barOption(trends.value)),pie=computed(()=>pieOption(stats.value)),line=computed(()=>balanceOption(trends.value))
async function load(){if(!month.value)return;const n=++serial;loading.value=true;error.value='';try{const [t,c,s]=await Promise.all([api.get('/statistics/trends',{params:{from:shiftMonth(month.value,1-span.value),to:month.value}}),api.get('/statistics/categories',{params:{month:month.value}}),api.get('/statistics/summary',{params:{month:month.value}})]);if(n===serial){trends.value=t;stats.value=c;summary.value=s}}catch(e){if(n===serial)error.value=e.message}finally{if(n===serial)loading.value=false}}
onMounted(load);watch([month,span],load)
</script><template><div class="view-toolbar"><span class="eyebrow">YOUR SPENDING, IN PERSPECTIVE</span><div class="toolbar-actions"><el-select v-model="span" aria-label="统计跨度" style="width:130px"><el-option label="最近6个月" :value="6"/><el-option label="最近12个月" :value="12"/></el-select><el-date-picker v-model="month" type="month" value-format="YYYY-MM" :clearable="false" aria-label="统计月份"/></div></div><div v-loading="loading"><StateBox :error="error" @retry="load"><section class="panel"><div class="panel-heading"><div><h2>月度收支对比</h2><p>{{shiftMonth(month,1-span)}} 至 {{month}} · 单位：元</p></div><span class="subtle-label">所选月结余 {{money(summary.balance)}}</span></div><Chart :option="bar" label="各月收入和支出对比柱状图" :height="300"/></section><div class="analysis-grid mt"><section class="panel"><div class="panel-heading"><div><h2>消费分类占比</h2><p>{{month}} 的支出去向</p></div></div><StateBox :empty="!stats.length" title="本月还没有支出" description="有了消费记录，就能看到各类别占比。"><Chart :option="pie" label="所选月份支出类别占比饼图" :height="260"/><div class="category-stats"><div v-for="s in stats" :key="s.categoryId"><span>{{s.name}}</span><b>{{money(s.amount)}}</b><small>{{s.percentage}}%</small></div></div></StateBox></section><section class="panel"><div class="panel-heading"><div><h2>结余变化</h2><p>月收入 − 月支出 · 单位：元</p></div></div><Chart :option="line" label="各月结余变化折线图" :height="300"/><p class="chart-footnote">结余为单个月的收支差额，不代表账户累计余额。</p></section></div><section class="panel mt"><div class="panel-heading"><div><h2>月度数据</h2><p>图表与下表使用同一组统计结果</p></div></div><el-table :data="trends"><el-table-column prop="month" label="月份" min-width="105"/><el-table-column label="收入" min-width="140" align="right"><template #default="{row}"><span class="income">{{money(row.income)}}</span></template></el-table-column><el-table-column label="支出" min-width="140" align="right"><template #default="{row}">{{money(row.expense)}}</template></el-table-column><el-table-column label="结余" min-width="140" align="right"><template #default="{row}"><b>{{money(row.balance)}}</b></template></el-table-column></el-table></section></StateBox></div></template>
